 .quick-view-dialog[open]::backdrop{animation:quick-view-backdrop-enter .24s ease both}.quick-view-dialog.is-closing[open]{animation:quick-view-exit .2s ease forwards!important}.quick-view-dialog.is-closing[open]::backdrop{animation:quick-view-backdrop-exit .2s ease forwards}@keyframes quick-view-backdrop-enter{from{opacity:0}to{opacity:1}}@keyframes quick-view-backdrop-exit{to{opacity:0}}@keyframes quick-view-exit{to{opacity:0;transform:translateY(10px) scale(.985)}}@media(prefers-reduced-motion:reduce){.quick-view-dialog[open],.quick-view-dialog.is-closing[open],.quick-view-dialog[open]::backdrop{animation-duration:1ms!important}}.quick-view-dialog{overflow-x:hidden;overflow-y:auto}.quick-view-content,.quick-view-dialog .product-detail,.quick-view-dialog .product-gallery,.quick-view-dialog .product-info,.quick-view-dialog .product-info>*{min-width:0;max-width:100%}.quick-view-dialog .product-info .add-cart-form{display:block;width:100%;min-width:0}.quick-view-dialog .product-price-promotion,.quick-view-dialog .product-stock-status,.quick-view-dialog .product-personalization-panel{width:100%;max-width:100%;min-width:0}.quick-view-dialog .product-personalization-panel{padding:16px;margin:14px 0}.quick-view-dialog .product-personalization-panel .custom-field,.quick-view-dialog .product-personalization-panel textarea,.quick-view-dialog .product-personalization-panel input,.quick-view-dialog .product-personalization-panel select{width:100%;max-width:100%;min-width:0;box-sizing:border-box}.quick-view-dialog .product-purchase-row{grid-template-columns:minmax(90px,120px) minmax(0,1fr);gap:10px}.quick-view-dialog .product-purchase-row .product-add-button{width:100%;min-width:0}.quick-view-dialog .product-cart-feedback{max-width:100%;overflow-wrap:anywhere}
.quick-view-dialog .product-info{display:flex;flex-direction:column;gap:14px}.quick-view-dialog .product-info h1{margin:0}.quick-view-dialog .product-info .product-rating{align-self:flex-start;margin:0}.quick-view-dialog .product-info .price{margin:0}.quick-view-dialog .product-info>.muted,.quick-view-dialog .product-info>p{margin:0}.quick-view-dialog .product-info .add-cart-form{display:flex;flex-direction:column;align-items:stretch;gap:14px;margin:0}.quick-view-dialog .product-info .product-price-promotion,.quick-view-dialog .product-info .product-personalization-panel,.quick-view-dialog .product-info .product-purchase-row,.quick-view-dialog .product-info .product-stock-status{margin-top:0;margin-bottom:0}.product-grid .product-card-media .product-card-quick-preview{position:absolute;top:64px;right:12px;width:44px;min-width:44px;height:44px;min-height:44px;flex:0 0 44px;justify-self:auto;gap:0;padding:0;border-radius:50%}.product-grid[data-columns="1"] .product-card-media .product-card-quick-preview,.product-grid[data-columns="2"] .product-card-media .product-card-quick-preview,.product-grid[data-columns="3"] .product-card-media .product-card-quick-preview,.product-grid[data-columns="4"] .product-card-media .product-card-quick-preview{width:44px;min-width:44px;height:44px;min-height:44px;flex:0 0 44px;justify-self:auto;gap:0;padding:0;border-radius:50%}
</style>
<script>
(()=>{if(window.__giftchetaQuickView)return;window.__giftchetaQuickView=true;let dialog=null,request=null,closeTimer=null,lockedScrollY=0,previousBodyStyles=null,pendingNavigationUrl=null;function closeDialog(){if(!dialog?.open||dialog.classList.contains('is-closing'))return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){dialog.close();return}dialog.classList.add('is-closing');closeTimer=window.setTimeout(()=>{if(dialog?.open&&dialog.classList.contains('is-closing'))dialog.close()},210)}function getDialog(){if(dialog)return dialog;dialog=document.createElement('dialog');dialog.className='quick-view-dialog';dialog.setAttribute('aria-label','Подробен преглед на продукта');const shell=document.createElement('div');shell.className='quick-view-shell';const close=document.createElement('button');close.className='site-close-button quick-view-close';close.type='button';close.setAttribute('aria-label','Затвори прегледа');close.dataset.quickViewClose='';close.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m6 6 12 12M18 6 6 18"/></svg>';const content=document.createElement('div');content.className='quick-view-content';shell.append(close,content);dialog.append(shell);dialog.addEventListener('click',event=>{if(event.target===dialog||event.target.closest('[data-quick-view-close]'))closeDialog();else if(event.target.closest('a.quick-view-product-page-link')){pendingNavigationUrl=event.target.closest('a.quick-view-product-page-link').href;closeDialog()}else if(event.target.closest('a'))event.preventDefault()});dialog.addEventListener('cancel',event=>{event.preventDefault();closeDialog()});dialog.addEventListener('close',()=>{clearTimeout(closeTimer);closeTimer=null;dialog.classList.remove('is-closing');request?.abort();document.body.classList.remove('quick-view-open');if(previousBodyStyles){for(const [property,value] of Object.entries(previousBodyStyles))document.body.style[property]=value;previousBodyStyles=null;window.scrollTo(0,lockedScrollY)}if(pendingNavigationUrl){const href=pendingNavigationUrl;pendingNavigationUrl=null;window.giftchetaNavigate?window.giftchetaNavigate(href):window.location.assign(href)}});document.body.append(dialog);return dialog}function quickViewSkeleton(){return `<div class="quick-view-skeleton" role="status" aria-label="Зареждаме подробностите за продукта"><span class="quick-view-skeleton-sr">Зареждаме подробностите за продукта…</span><div class="quick-view-skeleton-gallery" aria-hidden="true"><div class="quick-view-skeleton-block quick-view-skeleton-stage"></div><div class="quick-view-skeleton-thumbs"><i class="quick-view-skeleton-block quick-view-skeleton-thumb"></i><i class="quick-view-skeleton-block quick-view-skeleton-thumb"></i><i class="quick-view-skeleton-block quick-view-skeleton-thumb"></i><i class="quick-view-skeleton-block quick-view-skeleton-thumb"></i></div></div><div class="quick-view-skeleton-info" aria-hidden="true"><i class="quick-view-skeleton-block quick-view-skeleton-badge"></i><i class="quick-view-skeleton-block quick-view-skeleton-title"></i><i class="quick-view-skeleton-block quick-view-skeleton-title short"></i><i class="quick-view-skeleton-block quick-view-skeleton-line"></i><div class="quick-view-skeleton-description"><i class="quick-view-skeleton-block quick-view-skeleton-line"></i><i class="quick-view-skeleton-block quick-view-skeleton-line"></i><i class="quick-view-skeleton-block quick-view-skeleton-line"></i></div><i class="quick-view-skeleton-block quick-view-skeleton-stock"></i><i class="quick-view-skeleton-block quick-view-skeleton-price"></i><div class="quick-view-skeleton-variants"><div class="quick-view-skeleton-variant"><i class="quick-view-skeleton-block quick-view-skeleton-label"></i><div class="quick-view-skeleton-options"><i class="quick-view-skeleton-block quick-view-skeleton-swatch"></i><i class="quick-view-skeleton-block quick-view-skeleton-swatch"></i><i class="quick-view-skeleton-block quick-view-skeleton-swatch"></i></div></div><div class="quick-view-skeleton-variant"><i class="quick-view-skeleton-block quick-view-skeleton-label"></i><div class="quick-view-skeleton-options"><i class="quick-view-skeleton-block quick-view-skeleton-size"></i><i class="quick-view-skeleton-block quick-view-skeleton-size"></i></div></div></div><div class="quick-view-skeleton-custom"><i class="quick-view-skeleton-block quick-view-skeleton-line"></i><i class="quick-view-skeleton-block quick-view-skeleton-textarea"></i></div><div class="quick-view-skeleton-purchase"><i class="quick-view-skeleton-block quick-view-skeleton-quantity"></i><i class="quick-view-skeleton-block quick-view-skeleton-button"></i></div><i class="quick-view-skeleton-block quick-view-skeleton-shipping"></i></div></div>`}async function open(trigger){const card=trigger.closest('.product-card'),href=card?.querySelector('.product-card-body h3 a')?.href;if(!card||!href)return;const modal=getDialog(),content=modal.querySelector('.quick-view-content');clearTimeout(closeTimer);closeTimer=null;modal.classList.remove('is-closing');request?.abort();request=new AbortController();content.innerHTML=quickViewSkeleton();content.setAttribute('aria-busy','true');if(!modal.open){lockedScrollY=window.scrollY;previousBodyStyles={position:document.body.style.position,top:document.body.style.top,left:document.body.style.left,right:document.body.style.right,width:document.body.style.width,overflow:document.body.style.overflow,paddingRight:document.body.style.paddingRight};const scrollbarWidth=Math.max(0,window.innerWidth-document.documentElement.clientWidth);document.body.style.position='fixed';document.body.style.top='-'+lockedScrollY+'px';document.body.style.left='0';document.body.style.right='0';document.body.style.width='100%';document.body.style.overflow='hidden';if(scrollbarWidth)document.body.style.paddingRight=scrollbarWidth+'px';document.body.classList.add('quick-view-open');modal.showModal()};try{const response=await fetch(href,{credentials:'same-origin',signal:request.signal,headers:{Accept:'application/vnd.giftcheta.fragment+html'}});if(!response.ok)throw new Error('Не успяхме да заредим продукта.');const html=await response.text(),template=document.createElement('template');template.innerHTML=html;const main=template.content.querySelector('main.shell.main'),detail=main?.querySelector('.product-detail');if(!detail)throw new Error('Не намерихме подробностите за продукта.');const styles=[...main.querySelectorAll(':scope > style')];content.replaceChildren(...styles.map(style=>style.cloneNode(true)),detail);content.removeAttribute('aria-busy');content.querySelectorAll('style').forEach(style=>style.classList.add('quick-view-extra-styles'));for(const oldScript of [...main.querySelectorAll('script')]){const script=document.createElement('script');for(const attr of oldScript.attributes)script.setAttribute(attr.name,attr.value);script.textContent=oldScript.textContent;content.append(script)}}catch(error){if(error.name!=='AbortError'){content.removeAttribute('aria-busy');content.innerHTML='<div class="quick-view-error" role="alert">Не успяхме да заредим подробностите. <a href="'+href+'">Отвори продуктовата страница</a>.</div>'}}}document.addEventListener('click',event=>{const trigger=event.target.closest('[data-quick-view-trigger]');if(!trigger)return;event.preventDefault();open(trigger)});window.addEventListener('cart:open',()=>{if(dialog?.open)closeDialog()});})();
</script>
